import{Z as t,e as n,f as a,a0 as o}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Slack","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/messaging/slack.md","filePath":"integrations/messaging/slack.md","lastUpdated":1780377007000}'),i={name:"integrations/messaging/slack.md"};function s(r,e,l,c,h,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h1><p>Connect Slack to send a message when a visitor completes your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Messaging</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Slack</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-slack-api" tabindex="-1">Step 2. Connect to the Slack API <a class="header-anchor" href="#step-2-connect-to-the-slack-api" aria-label="Permalink to &quot;Step 2. Connect to the Slack API&quot;">​</a></h3><ol><li>Go to the <a href="https://api.slack.com/apps?new_app=1" target="_blank">Slack App Center</a>.</li><li>Create a new app, by entering an <strong>App Name</strong> and <strong>Development Slack Workspace</strong>.</li><li>In the left-hand sidebar, under <strong>Settings</strong>, click <strong>Basic Information</strong>.</li><li>Under the <strong>App Credentials</strong> section, copy the <strong>Client ID</strong> and <strong>Client Secret</strong> values and paste into the fields in Formie.</li><li>In the left-hand sidebar, under <strong>Features</strong>, click <strong>OAuth &amp; Permissions</strong>.</li><li>In the section <strong>Redirect URLs</strong>, click the <strong>Add New Redirect URL</strong> button and enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Then click the <strong>Add</strong> button, then click the <strong>Save URLs</strong> button.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Slack, where you must approve Formie to access your Slack account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Set the recipient or channel supported by the integration. Use the variable picker to include the submitted values your team needs in the message.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Check the intended recipient or channel for the test message and verify that its values match the submission.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
